let spectatorIndex=0,previousSpectate=false;let gameOverShown=false,previousMint=false,previousDoor=false,previousBoard=false,previousRepair=false,pauseOpen=false,selectedInventoryHand='primary';let root,canvas,ctx,miniCanvas,menu,labels,session=null,world=null,raf=0,last=0,net=0,inputs=new Map(),invite=null,localInput={},inventoryOpen=false,inventoryPanel=null,previousUse=false,previousToggle=false,camera={x:0,y:0};
const BIND_DEFAULTS={up:'KeyW',down:'KeyS',left:'KeyA',right:'KeyD',sprint:'ShiftLeft',attack:'Space',interact:'KeyE',inventory:'KeyI',heal:'KeyC',door:'KeyF',board:'KeyB',repair:'KeyR',primary:'Digit1',secondary:'Digit2'};
let binds={...BIND_DEFAULTS};try{const saved=JSON.parse(localStorage.getItem('deadzone-keybinds')||'{}');for(const [action,code] of Object.entries(saved))if(action in binds&&typeof code==='string')binds[action]=code;}catch{}
