let totalPlaytimeFlush=0;const totalTimeKey=()=> 'deadzone-total-playtime-v1-'+String(who()||'guest');const getTotalTime=()=>{try{return Math.max(0,Number(localStorage.getItem(totalTimeKey()))||0)}catch{return 0}};let totalPlaytime=getTotalTime();function flushTotalPlaytime(){try{localStorage.setItem(totalTimeKey(),String(totalPlaytime))}catch(e){console.warn('Dead Zone playtime save failed',e)}}
let saveClock=0,fullStateClock=0,doorSyncClock=0,lastGuestState=0,lastInputSignature='',lastInputSent=0;let gameChatLog=null,gameChatInput=null,lastGameChatAt=0;let guestVisuals=new Map(),guestPrediction=null;
function saveGame(){if(!session||session.mode!=='host'||session.phase!=='play'||!world||world.ended)return false;try{const copy=JSON.parse(JSON.stringify(world));copy.players=copy.players.filter(p=>p.id===who());if(!copy.players.length)return false;copy.effects=[];copy.blood=[];copy.shots=[];localStorage.setItem(saveKey(),JSON.stringify({version:1,savedAt:Date.now(),mode:world.mode,difficulty:world.difficulty,world:copy}));return true;}catch(e){console.warn('Dead Zone save failed:',e);return false;}}
function readSave(){try{const v=JSON.parse(localStorage.getItem(saveKey())||'null');return v?.version===1&&v.world&&Array.isArray(v.world.players)&&v.world.players.length===1&&v.world.players[0].id===who()&&!v.world.ended?v:null;}catch{return null;}}
function continueGame(){const saved=readSave();if(!saved||!session||session.mode!=='host')return;world=saved.world;world.effects=[];world.blood=[];world.shots=[];world.players[0].vx=0;world.players[0].vy=0;session.gameMode=world.mode||saved.mode||'story';session.difficulty=world.difficulty||saved.difficulty||'normal';session.phase='play';saveClock=0;gameOverShown=false;pauseOpen=false;menu.style.display='none';group({t:'dz-start',id:session.id,world});canvas.focus();}
