const itemDefs={boards:{name:'Wooden Boards',type:'material'},bat:{name:'Rusty Spiked Bat',type:'weapon',damage:20,range:49,cool:.48},crowbar:{name:'Crowbar',type:'weapon',damage:30,range:55,cool:.4},axe:{name:'Fire Axe',type:'weapon',damage:44,range:62,cool:.56},pistol:{name:'Old Pistol',type:'weapon',damage:25,range:650,cool:.29},shotgun:{name:'Shotgun',type:'weapon',damage:48,range:480,cool:.68},jacket:{name:'Leather Jacket',type:'armor',defense:.14},vest:{name:'Kevlar Vest',type:'armor',defense:.32},heavy:{name:'Riot Armor',type:'armor',defense:.49},medkit:{name:'Medkit',type:'consumable'},mints:{name:'Care Mints',type:'consumable'},pipe:{name:'Steel Pipe',type:'weapon',damage:26,range:56,cool:.4},machete:{name:'Machete',type:'weapon',damage:40,range:68,cool:.4},sledge:{name:'Sledgehammer',type:'weapon',damage:72,range:70,cool:.95},katana:{name:'Katana',type:'weapon',damage:52,range:77,cool:.42},hammer:{name:'Hammer',type:'weapon',damage:33,range:49,cool:.42},revolver:{name:'Revolver',type:'weapon',damage:52,range:720,cool:.52},smg:{name:'SMG',type:'weapon',damage:18,range:530,cool:.12},rifle:{name:'Assault Rifle',type:'weapon',damage:33,range:760,cool:.2},sniper:{name:'Marksman Rifle',type:'weapon',damage:86,range:1100,cool:1.05},doublebarrel:{name:'Double Barrel Shotgun',type:'weapon',damage:70,range:440,cool:.96},tactical:{name:'Tactical Vest',type:'armor',defense:.40},military:{name:'Military Armor',type:'armor',defense:.55},hazmat:{name:'Hazmat Suit',type:'armor',defense:.25},scrapvest:{name:'Scrap Vest',type:'armor',defense:.20},ammoBox:{name:'Ammo Box',type:'consumable'},bandage:{name:'Bandages',type:'consumable'},energy:{name:'Energy Drink',type:'consumable'},chainsaw:{name:'Chainsaw',type:'weapon',damage:22,range:69,cool:.12}};
const player=(id,i)=>({id,x:MAPW/2+(i%2)*34-17,y:MAPH/2+Math.floor(i/2)*34-17,vx:0,vy:0,hp:100,kills:0,cool:0,invuln:0,color:['#93d1ff','#f7c576','#cda5ff','#99e3ab'][i],inventory:['bat'],weaponLevels:{bat:1},primary:'bat',secondary:null,activeSlot:'primary',weapon:'bat',armor:null,ammo:0,face:0,swing:0,medkits:0,mints:0,boards:0,stamina:100,energy:0,reviveHold:0,reviveTarget:null,chestHold:0,chestTarget:null,chestComplete:false});
function makeMap(){const houses=[],chests=[];for(let y=180;y<MAPH-190;y+=430)for(let x=180;x<MAPW-190;x+=500){if(Math.hypot(x-MAPW/2,y-MAPH/2)<340)continue;const n=houses.length,type=n%5,w=[230,195,260,215,245][type],h=[185,215,175,195,225][type],px=x+(n%3)*17,py=y+(n%2)*19;houses.push({x:px,y:py,w,h,type,doorX:px+w/2,doorY:py+h,doorOpen:false,doorHp:100,doorMaxHp:100,boards:0});chests.push({id:chests.length,x:px+45+n%3*45,y:py+68+n%2*40,opened:false});if(n%3===0)chests.push({id:chests.length,x:px+w-48,y:py+50,opened:false});}return{houses,chests};}
const lootPool=['crowbar','axe','pistol','shotgun','jacket','vest','heavy','medkit','medkit','mints','mints','boards','boards','pipe','machete','sledge','katana','hammer','revolver','smg','rifle','sniper','doublebarrel','tactical','military','hazmat','scrapvest','ammoBox','ammoBox','bandage','energy','chainsaw'];
const ZOMBIE_TYPES={walker:{hp:1,speed:1,color:'#4d6852'},runner:{hp:.7,speed:1.55,color:'#a56c4c'},brute:{hp:2.2,speed:.72,color:'#746b50'},crawler:{hp:.55,speed:1.25,color:'#738e61'},armored:{hp:3,speed:.68,color:'#5a6978'},stalker:{hp:1.15,speed:1.38,color:'#675977'},sprinter:{hp:.75,speed:1.95,color:'#b05a60'},toxic:{hp:1.35,speed:.9,color:'#82a54e'},berserker:{hp:2.0,speed:1.26,color:'#a34848'},juggernaut:{hp:4,speed:.55,color:'#816956'},boss:{hp:17,speed:.78,color:'#bd4c44'}};
function chooseZombieType(wave){const choices=['walker','walker','walker','runner','crawler'];if(wave>=3)choices.push('stalker','toxic');if(wave>=5)choices.push('armored','brute','sprinter');if(wave>=7)choices.push('berserker');if(wave>=9)choices.push('juggernaut');return choices[Math.floor(Math.random()*choices.length)];}
function zombieSpawn(boss=false){world.zombieSerial=world.zombieSerial||0;const living=world.players.filter(p=>p.hp>0);const target=living[Math.floor(Math.random()*living.length)]||world.players[0];let x=target.x+600,y=target.y;for(let attempt=0;attempt<28;attempt++){const angle=Math.random()*Math.PI*2,dist=520+Math.random()*180;const nx=Math.max(15,Math.min(MAPW-15,target.x+Math.cos(angle)*dist)),ny=Math.max(15,Math.min(MAPH-15,target.y+Math.sin(angle)*dist));if(!solid(nx,ny,14)){x=nx;y=ny;break;}}const kind=boss?'boss':chooseZombieType(world.wave),cfg=ZOMBIE_TYPES[kind];const hp=Math.round(cfg.hp*(38+world.wave*12)*(DIFFICULTIES[world.difficulty||'normal']||DIFFICULTIES.normal).hp);return{netId:++world.zombieSerial,kind,maxHp:hp,hp,x,y,speed:cfg.speed*(90+Math.min(110,world.wave*6))*(DIFFICULTIES[world.difficulty||'normal']||DIFFICULTIES.normal).speed,attack:0,boss};}
function newWorld(ids){const m=makeMap();return{mode:session?.gameMode||'endless',story:{stage:0,hold:0,defense:0},effects:[],blood:[],eventSerial:0,time:0,won:false,wave:0,difficulty:session?.difficulty||'normal',score:0,players:ids.map((id,i)=>player(id,i)),zombies:[],zombieSerial:0,shots:[],spawned:0,remaining:0,between:2,ended:false,houses:m.houses,chests:m.chests,drops:[],dropSerial:0,notice:''};}
function houseAt(x,y){return(world?.houses||[]).find(h=>x>h.x+10&&x<h.x+h.w-10&&y>h.y+10&&y<h.y+h.h-10);}
function nearDoor(p){let best=null,d=85;for(const h of world?.houses||[]){let dist=Math.hypot(p.x-h.doorX,p.y-h.doorY);if(dist<d){best=h;d=dist;}}return best;}
function carCollision(x,y,r=12){for(let i=0;i<70;i++){const cx=90+(i%7)*500,cy=155+Math.floor(i/7)*245;const nearX=Math.max(cx-24,Math.min(x,cx+29)),nearY=Math.max(cy-43,Math.min(y,cy+47));if((x-nearX)**2+(y-nearY)**2<r*r)return true;}return false;}
function solid(x,y,r=12){if(x<r||y<r||x>MAPW-r||y>MAPH-r||carCollision(x,y,r))return true;for(const h of world?.houses||[]){const t=6,half=34;const overlaps=(ax,ay,bx,by)=>{const closestX=Math.max(ax,Math.min(x,bx)),closestY=Math.max(ay,Math.min(y,by));return (x-closestX)**2+(y-closestY)**2<r*r;};if(overlaps(h.x-t,h.y-t,h.x+t,h.y+h.h+t)||overlaps(h.x+h.w-t,h.y-t,h.x+h.w+t,h.y+h.h+t)||overlaps(h.x-t,h.y-t,h.x+h.w+t,h.y+t))return true;if(overlaps(h.x-t,h.y+h.h-t,h.doorX-half,h.y+h.h+t)||overlaps(h.doorX+half,h.y+h.h-t,h.x+h.w+t,h.y+h.h+t))return true;if(!h.doorOpen&&h.doorHp>0&&overlaps(h.doorX-half,h.doorY-t,h.doorX+half,h.doorY+t))return true;}return false;}
function repairDoor(p){const h=nearDoor(p);if(!h){world.notice='Get closer to a door to repair it';return;}if(h.doorHp<=0){if((p.boards||0)<2){world.notice='You need 2 wooden boards to rebuild this door';return;}p.boards-=2;h.doorMaxHp=100+(h.boards||0)*55;h.doorHp=Math.min(65,h.doorMaxHp);h.doorOpen=false;world.notice=name(p.id)+' rebuilt a destroyed door (65 HP)';return;}if(h.doorHp>=h.doorMaxHp){world.notice='Door is already fully repaired';return;}if(!p.boards){world.notice='You need a wooden board to repair the door';return;}p.boards--;h.doorHp=Math.min(h.doorMaxHp,h.doorHp+65);world.notice=name(p.id)+' repaired a door (+65 HP)';}
function toggleDoor(p,board=false){const h=nearDoor(p);if(!h)return false;if(board){if(h.doorHp<=0){world.notice='This door is destroyed';return false;}if(h.boards>=4){world.notice='Door fully reinforced (4/4)';return false;}if(!(p.boards>0)){world.notice='You need wooden boards! Loot them from chests.';return false;}p.boards--;h.boards=Math.min(4,(h.boards||0)+1);h.doorMaxHp=100+h.boards*55;h.doorHp=Math.min(h.doorMaxHp,h.doorHp+55);h.doorOpen=false;world.notice=name(p.id)+' boarded a door ('+h.boards+'/4)';}else{if(h.doorHp<=0){world.notice='This door is broken';return true;}h.doorOpen=!h.doorOpen;world.notice=name(p.id)+(h.doorOpen?' opened':' closed')+' a door';}return true;}
function move(entity,dx,dy,r=12){const steps=Math.max(1,Math.ceil(Math.hypot(dx,dy)/Math.max(4,r*.75)));for(let i=0;i<steps;i++){if(!solid(entity.x+dx/steps,entity.y,r))entity.x+=dx/steps;else if(entity.vx)entity.vx=0;if(!solid(entity.x,entity.y+dy/steps,r))entity.y+=dy/steps;else if(entity.vy)entity.vy=0;}}
function grantLoot(p,id){if(itemDefs[id]?.type==='weapon'&&itemDefs[id].range>100)p.ammo+=24;if(id==='ammoBox'){p.ammo+=48;return;}if(id==='bandage'){p.hp=Math.min(100,p.hp+28);return;}if(id==='energy'){p.energy=(p.energy||0)+1;world.notice=name(p.id)+' picked up an energy drink';return;}if(id==='medkit')p.medkits++;else if(id==='mints')p.mints=(p.mints||0)+2;else if(id==='boards')p.boards=(p.boards||0)+2;else {p.inventory.push(id);if(itemDefs[id]?.type==='weapon'){p.weaponLevels=p.weaponLevels||{};p.weaponLevels[id]=Math.max(p.weaponLevels[id]||0,Math.min(5,1+Math.floor(Math.max(0,world.wave-1)/3)));}if(itemDefs[id]?.type==='armor'&&!p.armor)p.armor=id;}world.notice=name(p.id)+' collected '+(itemDefs[id]?.name||id)+'!';}
const LOOT_WEIGHTS={boards:18,mints:17,bandage:14,medkit:10,ammoBox:12,energy:10,pipe:12,hammer:11,crowbar:10,jacket:9,scrapvest:8,axe:7,pistol:6,machete:6,vest:6,hazmat:5,revolver:4,shotgun:4,smg:3,tactical:3,sledge:2.5,rifle:2,katana:1.7,doublebarrel:1.5,heavy:1.3,military:.6,sniper:.5,chainsaw:.35};
const LOOT_UNLOCK={smg:3,sledge:4,rifle:5,katana:5,doublebarrel:5,heavy:5,military:7,sniper:7,chainsaw:6};
function randomLoot(wave=1,options){const available=(options||lootPool).filter(id=>(LOOT_UNLOCK[id]||1)<=wave);const pool=available.length?available:['boards','mints','bandage'];let total=0;for(const id of pool)total+=LOOT_WEIGHTS[id]||1;let roll=Math.random()*total;for(const id of pool){roll-=LOOT_WEIGHTS[id]||1;if(roll<0)return id;}return pool[pool.length-1];}
function spawnDrop(){const living=world.players.filter(p=>p.hp>0);if(!living.length)return;const p=living[Math.floor(Math.random()*living.length)],pool=lootPool;const id=randomLoot(world.wave,pool);for(let i=0;i<20;i++){const angle=Math.random()*Math.PI*2,dist=105+Math.random()*170,x=Math.max(20,Math.min(MAPW-20,p.x+Math.cos(angle)*dist)),y=Math.max(20,Math.min(MAPH-20,p.y+Math.sin(angle)*dist));if(!solid(x,y,23)){world.drops.push({id:++world.dropSerial,item:id,x,y});world.notice='A supply drop landed nearby!';return;}}}
function zombieLoot(z){if(Math.random()>.24)return;const pool=['mints','boards','medkit','bandage','ammoBox','energy','crowbar','pipe','machete','hammer','axe','pistol','revolver','smg','shotgun','rifle','chainsaw','vest','tactical'];const id=randomLoot(world.wave,pool);world.drops.push({id:++world.dropSerial,item:id,x:z.x,y:z.y});}
function action(p,a){if(p.hp<=0)return;if(a.repair){repairDoor(p);return;}if(a.board){toggleDoor(p,true);return;}if(a.door){toggleDoor(p);return;}if(!a.use)return;let drop=null,dropDist=65;for(const d of world.drops||[]){const k=Math.hypot(d.x-p.x,d.y-p.y);if(k<dropDist){drop=d;dropDist=k;}}if(drop){world.drops=world.drops.filter(d=>d.id!==drop.id);grantLoot(p,drop.item);return;}const nearest=nearbyChest(p);if(nearest){p.chestHold=Math.min(1.25,(p.chestHold||0)+.05);return;}if(p.medkits&&p.hp<100){p.medkits--;p.hp=Math.min(100,p.hp+55);world.notice=name(p.id)+' used a medkit';}}
function equip(p,slot,hand='primary'){const id=p.inventory[slot];if(!itemDefs[id])return;if(itemDefs[id].type==='weapon'){const key=hand==='secondary'?'secondary':'primary';p[key]=id;p.activeSlot=key;p.weapon=id;}else if(itemDefs[id].type==='armor')p.armor=id;}
function swapWeapon(p,hand){const k=hand==='secondary'?'secondary':'primary';if(p[k]&&itemDefs[p[k]]?.type==='weapon'){p.activeSlot=k;p.weapon=p[k];}}

const button=(label,fn,parent=menu)=>{const b=document.createElement('button');b.textContent=label;b.style.cssText='padding:10px 17px;background:#345a56;border:1px solid #719c7f;border-radius:8px;color:white;cursor:pointer;margin:5px';b.onclick=fn;parent.append(b);return b;};
