function close(){flushTotalPlaytime();saveGame();pauseOpen=false;gameOverShown=false;inventoryOpen=false;if(inventoryPanel)inventoryPanel.style.display='none';if(session){if(session.mode==='host')group({t:'dz-end',id:session.id});else emit(session.host,{t:'dz-leave',id:session.id});}session=null;world=null;if(gameChatLog)gameChatLog.replaceChildren();guestVisuals.clear();lastInputSignature='';if(root)root.style.display='none';keys.clear();mouse.down=false;}
function returnToMenu(){close();invite=null;open();}
