function frame(now){raf=requestAnimationFrame(frame);if(!session||root.style.display==='none')return;const elapsed=Math.max(0,Math.min(.25,(now-(last||now))/1000));const dt=Math.min(.05,elapsed);last=now;if(session.phase==='play'&&world&&!world.ended){totalPlaytime+=elapsed;totalPlaytimeFlush+=elapsed;if(totalPlaytimeFlush>=5){flushTotalPlaytime();totalPlaytimeFlush=0;}}localInput=document.activeElement===gameChatInput?{}:input();if(pauseOpen||inventoryOpen)localInput={};if(session.phase==='play'){if(session.mode==='host'){if(!((pauseOpen||inventoryOpen)&&!peers().size))tick(dt);saveClock+=dt;if(saveClock>=12){saveGame();saveClock=0;}net+=dt;if(net>=.12){const full=fullStateClock>=6;const doors=doorSyncClock>=.7;const snapshot=full?world:{...world,houses:undefined,chests:undefined,blood:undefined,effects:undefined,shots:world.shots.slice(-24),zombies:world.zombies.map(z=>({netId:z.netId,x:z.x,y:z.y,hp:z.hp,maxHp:z.maxHp,kind:z.kind,hit:z.hit,speed:z.speed,attack:z.attack,boss:z.boss}))};group({t:'dz-state',id:session.id,world:snapshot,partial:!full,doors:!full&&doors?world.houses.map(h=>[h.doorOpen,h.doorHp,h.boards]):undefined});if(full)fullStateClock=0;if(doors)doorSyncClock=0;net=0;}fullStateClock+=dt;doorSyncClock+=dt;}else{net+=dt;const sig=JSON.stringify(localInput);net+=0;if((sig!==lastInputSignature&&net>=.04)||net>=.14){emit(session.host,{t:'dz-input',id:session.id,input:localInput});lastInputSignature=sig;net=0;}}}draw();}
