if(d.t==='dz-invite'){invite={from,id:d.id};if(session)return;build();const status=document.querySelector('#deadZoneInviteStatus');if(status)status.textContent=name(from)+' invited you to Dead Zone. Open Games → Dead Zone to join.';return;}
if(!session||d.id!==session.id)return;if(d.t==='dz-chat'&&typeof d.message==='string'){if(session.mode==='host'){if(!peers().has(from))return;addGameMessage(from,d.message);group({t:'dz-chat',id:session.id,from,message:d.message.slice(0,220)});}else if(from===session.host)addGameMessage(d.from||from,d.message);return;}
