 for(let i=0;i<75;i++){const x=(i*617+33)%MAPW,y=(i*367+91)%MAPH;if(x<camera.x||x>camera.x+W||y<camera.y||y>camera.y+H||houseAt(x,y))continue;ctx.fillStyle=i%4?'#7f80625a':'#bac0a080';ctx.fillRect(x,y,3+i%5,2+i%3);}
