function drawObjectives(){if(world.mode!=='story')return;const site=missionSites[Math.min(2,world.story.stage)],pulse=1+Math.sin((world.time||0)*3)*.08;ctx.save();ctx.strokeStyle='#d8c387';ctx.lineWidth=2;ctx.setLineDash([8,5]);ctx.beginPath();ctx.ellipse(site.x,site.y,65*pulse,65*pulse,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#f3dc9f';ctx.font='bold 11px monospace';ctx.textAlign='center';ctx.fillText(site.label,site.x,site.y-80);glow(site.x,site.y,90,'#a8bf85');ctx.restore();}
function drawAtmosphere(p){if(!world||!p)return;ctx.save();const x=p.x-camera.x,y=p.y-camera.y;const g=ctx.createRadialGradient(x,y,75,x,y,540);g.addColorStop(0,'#06101b00');g.addColorStop(.55,'#06101b25');g.addColorStop(1,'#020811ba');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.globalCompositeOperation='screen';ctx.translate(x,y);ctx.rotate(p.face||0);const beam=ctx.createRadialGradient(0,0,10,0,0,260);beam.addColorStop(0,'#e0d5a32a');beam.addColorStop(1,'#e0d5a300');ctx.fillStyle=beam;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,260,-.43,.43);ctx.closePath();ctx.fill();ctx.restore();if(p.invuln>.15){ctx.fillStyle='#cd33331c';ctx.fillRect(0,0,W,H);}}
function drawMiniMap(){if(!world||!miniCanvas)return;const mc=miniCanvas.getContext('2d');const size=260,x=0,y=0,scaleX=(size-20)/MAPW,scaleY=(size-20)/MAPH;mc.clearRect(0,0,size,size);mc.save();mc.fillStyle='#071a18ec';mc.fillRect(x,y,size,size);mc.strokeStyle='#87bba4';mc.lineWidth=2;mc.strokeRect(x+.5,y+.5,size-1,size-1);mc.fillStyle='#d5ead8';mc.textAlign='left';mc.font='bold 10px system-ui';mc.fillText('SECTOR RADAR',x+10,y+13);mc.save();mc.beginPath();mc.rect(x+9,y+20,size-18,size-29);mc.clip();const px=wx=>x+10+wx*scaleX,py=wy=>y+20+wy*scaleY;mc.strokeStyle='#52676277';mc.lineWidth=.6;for(const h of world.houses||[]){mc.strokeRect(px(h.x),py(h.y),h.w*scaleX,h.h*scaleY);}for(const z of world.zombies||[]){if(z.hp<=0)continue;mc.fillStyle=z.boss?'#ffb13b':ZOMBIE_TYPES[z.kind]?.color||'#ff6158';mc.beginPath();mc.arc(px(z.x),py(z.y),4,0,Math.PI*2);mc.fill();}for(const teammate of world.players||[]){mc.fillStyle=teammate.hp<=0?'#858585':teammate.id===who()?'#ffffff':'#5fbeff';mc.beginPath();mc.arc(px(teammate.x),py(teammate.y),teammate.id===who()?4:3,0,Math.PI*2);mc.fill();}mc.restore();mc.font='9px system-ui';mc.fillStyle='#d6e8dd';mc.fillText('● YOU   ● TEAM   ● INFECTED (TYPE COLOR)',x+9,y+size-5);mc.restore();}
function drawMissionHUD(p){if(!world||!p)return;ctx.save();ctx.fillStyle='#101a20e8';ctx.fillRect(18,18,340,74);ctx.fillStyle='#d4b67b';ctx.font='bold 10px monospace';ctx.textAlign='left';ctx.fillText(world.mode==='story'?'LAST SIGNAL / STORY':'SECTOR 07 / ENDLESS',30,36);ctx.font='bold 13px monospace';ctx.fillStyle='#eee5cf';const m=world.story;ctx.fillText(world.mode==='story'?['Recover the emergency cache','Restore the district radio','Hold the evacuation zone'][Math.min(2,m.stage)]:'Survive. Scavenge. Fortify.',30,56);ctx.font='11px monospace';ctx.fillStyle='#b1c5bc';if(world.mode==='story'){const site=missionSites[Math.min(2,m.stage)],d=Math.hypot(p.x-site.x,p.y-site.y);ctx.fillText((d<70?(m.stage<2?binds.interact.replace('Key','')+': Hold to interact':'Stay inside the marked zone'):Math.round(d)+'m to objective')+' · '+(m.stage<2?Math.floor(m.hold/(m.stage?4:2)*100)+'%':Math.floor(m.defense)+'/45s'),30,77);if(d>90){const a=Math.atan2(site.y-p.y,site.x-p.x);ctx.translate(W/2+Math.cos(a)*210,H/2+Math.sin(a)*150);ctx.rotate(a);ctx.fillStyle='#efce85';ctx.beginPath();ctx.moveTo(12,0);ctx.lineTo(-7,-7);ctx.lineTo(-7,7);ctx.fill();}}else ctx.fillText('Wave '+world.wave+' · '+(world.between>0?'Resupply in '+Math.ceil(world.between)+'s':'Horde approaching'),30,77);ctx.restore();}

